const softDeleteFilesInFolderTree = `-- name: SoftDeleteFilesInFolderTree :execrows
WITH RECURSIVE subtree AS (
    SELECT f0.id FROM folders f0
     WHERE f0.id = $1 AND f0.user_id = $2
    UNION ALL
    SELECT f.id FROM folders f
     JOIN subtree s ON f.parent_id = s.id
)
UPDATE files
   SET deleted_at = now(), updated_at = now()
 WHERE files.user_id = $2
   AND files.deleted_at IS NULL
   AND files.folder_id IN (SELECT subtree.id FROM subtree)
`

type SoftDeleteFilesInFolderTreeParams struct {
	ID     uuid.UUID
	UserID uuid.UUID
}

func (q *Queries) SoftDeleteFilesInFolderTree(ctx context.Context, arg SoftDeleteFilesInFolderTreeParams) (int64, error) {
	result, err := q.db.Exec(ctx, softDeleteFilesInFolderTree, arg.ID, arg.UserID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const softDeleteFolder = `-- name: SoftDeleteFolder :execrows
WITH RECURSIVE subtree AS (
    SELECT f0.id FROM folders f0
     WHERE f0.id = $1 AND f0.user_id = $2 AND f0.deleted_at IS NULL
    UNION ALL
    SELECT f.id FROM folders f
     JOIN subtree s ON f.parent_id = s.id
     WHERE f.deleted_at IS NULL
)
UPDATE folders
   SET deleted_at = now(), updated_at = now()
 WHERE folders.id IN (SELECT subtree.id FROM subtree)
`

type SoftDeleteFolderParams struct {
	ID     uuid.UUID
	UserID uuid.UUID
}

// SoftDeleteFolder moves a folder to trash. Its children go with it, in the
// same statement, so a partially trashed tree is not a state that can exist.
func (q *Queries) SoftDeleteFolder(ctx context.Context, arg SoftDeleteFolderParams) (int64, error) {
	result, err := q.db.Exec(ctx, softDeleteFolder, arg.ID, arg.UserID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

